        elif stripped.startswith('OVERRIDE'):
            if current_block is not None:
                blocks.append(current_block)
            parts = stripped.split()
            if len(parts) != 3 or parts[0] != 'OVERRIDE':
                return "PARSE_ERROR"
            current_block = {"type": "OVERRIDE", "name": parts[1], "id": parts[2], "directives": []}
        elif '=' in stripped:
            if current_block is None:
                return "PARSE_ERROR"
            if stripped.count('=') != 1:
                return "PARSE_ERROR"
