            key = key.strip()
            value = value.strip()
            if key not in ['Depends', 'Before', 'After', 'Needs', 'Requires', 'Alias', 'Phony']:
                return "PARSE_ERROR"
            if key == 'Phony' and value not in ['yes', 'no']:
                return "PARSE_ERROR"
            current_block['directives'].append((key, value))
        else:
            # Any other non-blank, non-comment line is an error
            return "PARSE_ERROR"

