    defined_targets = set()
    for block in blocks:
        defined_targets.add(block['name'])

    referenced_targets = set()
    for block in blocks:
        for key, value in block['directives']:
            if key in ['Depends', 'Before', 'After', 'Needs', 'Requires', 'Alias']:
                parts = value.split()
                for p in parts:
                    referenced_targets.add(p)

    universe = defined_targets.union(referenced_targets)

    # Phase 3: Alias resolution
    # Build alias graph from all Alias directives
    # Find connected components
    # Create canonical map

    # Build adjacency for alias relationships (undirected)
    adj = {name: set() for name in universe}
    for block in blocks:
        for key, value in block['directives']:
            if key == 'Alias':
                parts = value.split()
                for p in parts:
                    adj[block['name']].add(p)
                    adj[p].add(block['name'])

    # Find connected components
    visited = set()
    components = []  # list of sets of names
    for name in universe:
        if name not in visited:
            component = set()
            stack = [name]
            while stack:
                node = stack.pop()
                if node not in visited:
                    visited.add(node)
                    component.add(node)
                    for neighbor in adj.get(node, []):
                        if neighbor not in visited:
                            stack.append(neighbor)
            components.append(component)

    # Create canonical map: each name maps to its canonical name (min of component)
    canonical_map = {}
    for comp in components:
        canonical = min(comp)  # lexicographically smallest
        for name in comp:
            canonical_map[name] = canonical

    # Phase 4: Directive Accumulation
    # Separate TARGET blocks in order, OVERRIDE blocks with ids
    target_blocks_raw = []  # raw blocks that are TARGET, in order
    override_blocks_raw = []  # raw blocks that are OVERRIDE

    for block in blocks:
        if block['type'] == 'TARGET':
            target_blocks_raw.append(block)
        else:
            override_blocks_raw.append(block)

    # Sort override blocks by id (string comparison)
    override_blocks_raw.sort(key=lambda b: b['id'])

    # Initialize accumulators for all canonical names in universe
    accumulators = {}
    for name in universe:
        canon = canonical_map[name]
        accumulators[canon] = {
            'Depends': set(),
            'Before': set(),
            'After': set(),
            'Needs': set(),
            'Requires': set(),
            'Phony': None  # will default to 'no' later
        }

