        canon_name = canonical_map[block['name']]
        new_directives = []
        for key, value in block['directives']:
            if key in ['Depends', 'Before', 'After', 'Needs', 'Requires', 'Alias']:
                new_value_parts = []
                for part in value.split():
                    new_value_parts.append(canonical_map[part])
                new_value = ' '.join(new_value_parts)
                new_directives.append((key, new_value))
            elif key == 'Phony':
                new_directives.append((key, value))
            else:
                new_directives.append((key, value))
        for key, value in new_directives:
            if key in ['Depends', 'Before', 'After', 'Needs', 'Requires']:
                parts = value.split()
                for part in parts:
                    accumulators[canon_name][key].add(part)
            elif key == 'Phony':
                accumulators[canon_name]['Phony'] = value

    # Default Phony to "no"
    for name in accumulators:
        if accumulators[name]['Phony'] is None:
            accumulators[name]['Phony'] = 'no'

