    # graph[u] = set of v such that u must be executed before v
    graph = {name: set() for name in universe}
    for name in universe:
        acc = accumulators[name]
        # Depends = X means X must be before name -> edge X -> name
        for dep in acc['Depends']:
            graph[dep].add(name)
        # Before = Y means name must be before Y -> edge name -> Y
        for before in acc['Before']:
            graph[name].add(before)
        # After = Z means Z must be before name -> edge Z -> name
        for after in acc['After']:
            graph[after].add(name)
        # Needs = W means name must be before W -> edge name -> W
        for needs in acc['Needs']:
            graph[name].add(needs)
        # Requires = V means name must be before V -> edge name -> V
        for req in acc['Requires']:
            graph[name].add(req)

    # Phase 6: Cycle detection - find all SCCs
    # Using Tarjan's algorithm
    index_counter = [0]
    stack = []
    lowlinks = {}
    index = {}
    on_stack = {}
    sccs = []  # list of lists of nodes

    def strongconnect(node):
        index[node] = index_counter[0]
        lowlinks[node] = index_counter[0]
        index_counter[0] += 1
        stack.append(node)
        on_stack[node] = True

        for neighbor in graph.get(node, []):
            if neighbor not in index:
                strongconnect(neighbor)
                lowlinks[node] = min(lowlinks[node], lowlinks[neighbor])
            elif on_stack.get(neighbor, False):
                lowlinks[node] = min(lowlinks[node], index[neighbor])

        if lowlinks[node] == index[node]:
            scc = []
