                w = stack.pop()
                on_stack[w] = False
                scc.append(w)
                if w == node:
                    break
            sccs.append(scc)

    for node in universe:
        if node not in index:
            strongconnect(node)

    # Identify cycles: SCC with size >= 2 OR size == 1 with self-loop
    cycles = []
    for scc in sccs:
        if len(scc) >= 2:
            cycles.append(sorted(scc))
        elif len(scc) == 1:
            node = scc[0]
            if node in graph[node]:  # self-loop
                cycles.append([node])

    # Sort cycles lexicographically
    cycles.sort()

    # Phase 7: Topological ordering of condensation graph
    # Map each node to its SCC index
    scc_of_node = {}
    scc_list = []  # the actual scc lists
    for i, scc in enumerate(sccs):
        scc_list.append(scc)
        for node in scc:
            scc_of_node[node] = i

    # Representatives for each SCC
    scc_representatives = [min(scc) for scc in scc_list]

    # Build condensation graph edges
    condensation_adj = {i: set() for i in range(len(sccs))}
    for u in universe:
        u_scc = scc_of_node[u]
        for v in graph[u]:
            v_scc = scc_of_node[v]
            if u_scc != v_scc:
                condensation_adj[u_scc].add(v_scc)

    # Kahn's algorithm with sorting by representative
    in_degree = {i: 0 for i in range(len(sccs))}
    for u in range(len(sccs)):
        for v in condensation_adj[u]:
            in_degree[v] += 1

    ready = [i for i in range(len(sccs)) if in_degree[i] == 0]
    ready.sort(key=lambda i: scc_representatives[i])

    order_sccs = []  # list of SCC indices in topological order
    while ready:
        curr = ready.pop(0)
        order_sccs.append(curr)
        for v in condensation_adj[curr]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                ready.append(v)
        ready.sort(key=lambda i: scc_representatives[i])

    # Build output order: for each SCC in order_sccs, list its members in lex order
    order = []
    for scc_idx in order_sccs:
        scc = scc_list[scc_idx]
        for node in sorted(scc):
            order.append(node)

    # Phase 8: Output JSON
    result = {"order": order, "cycles": cycles}
    return json.dumps(result, separators=(',', ':'))
